# G-level count of Spence quadruples (abelian G = prod Z_d, H generated by coordinatewise multipliers, Spence target -4, all row sums +1), chunked; independent of the K-level engine and of gbf.py
# (independent code of the judge of search/NOTES.md section 92).  The main block re-counts the exhaustively empty shapes p = 719 (K = 479, r = 3) and p = 739 (K = 211, r = 7) and two positive controls.
import numpy as np, itertools, sys, math
from collections import defaultdict
def count(dims,mults,chunk=20000,verbose=False):
    pts=list(itertools.product(*[range(d) for d in dims])); idx={p:i for i,p in enumerate(pts)}; n=len(pts)
    H={tuple([1]*len(dims))}; fr=list(H)
    while fr:
        x=fr.pop()
        for m in mults:
            y=tuple((a*b)%d for a,b,d in zip(x,m,dims))
            if y not in H: H.add(y); fr.append(y)
    lab=[-1]*n; sizes=[]
    for p in pts:
        if lab[idx[p]]<0:
            o={tuple((a*b)%d for a,b,d in zip(p,h,dims)) for h in H}
            for q in o: lab[idx[q]]=len(sizes)
            sizes.append(len(o))
    O=len(sizes); size=np.array(sizes); lab=np.array(lab)
    axes=tuple(range(1,len(dims)+1))
    vecs=[]
    for s in range(0,1<<O,chunk):
        ids=np.arange(s,min(1<<O,s+chunk),dtype=np.int64)
        X=1-2*((ids[:,None]>>np.arange(O))&1); X=X[(X@size)==1]
        if len(X)==0: continue
        full=X[:,lab].reshape((len(X),)+tuple(dims)).astype(np.float64)
        F=np.fft.fftn(full,axes=axes)
        P=np.rint(np.fft.ifftn(np.abs(F)**2,axes=axes).real).astype(np.int64).reshape(len(X),-1)[:,1:]
        vecs.append(P)
    if not vecs: return O,0,0,len(H)
    P=np.concatenate(vecs)
    U,inv=np.unique(P,axis=0,return_inverse=True); mult=np.bincount(inv.ravel()); L=len(U)
    rng=np.random.default_rng(1); w=rng.integers(1,2**40,size=P.shape[1],dtype=np.int64)
    h=U@w; ht=int(np.full(P.shape[1],-4)@w)
    d=defaultdict(list)
    for i in range(L):
        for j in range(L): d[int(h[i]+h[j])].append((i,j))
    tot=0; tgt=np.full(P.shape[1],-4)
    for key,lst in d.items():
        need=ht-key
        if need in d:
            for (i,j) in lst:
                for (k,l) in d[need]:
                    if np.array_equal(U[i]+U[j]+U[k]+U[l],tgt): tot+=int(mult[i])*int(mult[j])*int(mult[k])*int(mult[l])
    return O,L,tot,len(H)
if __name__=="__main__":
    from sympy import primitive_root
    # (A) p=719: K=479, r=3, H_K=<2>
    print('A p=719 K=[479] r=3 <2>:',count((479,3),[(2,1)]))
    # (B) p=739: K=211, r=7, H_K=<4>, squares of F_7*
    g7=primitive_root(7); sq=pow(g7,2,7)
    print('B p=739 K=[211] r=7 <4>:',count((211,7),[(1,sq),(4,1)]))
    # positive control for the pipeline: G=Z_3 x Z_3 and Z_3 x Z_7 shapes with known counts (x16 for unnormalised)
    print('control Z3xF3 trivial (norm count; x16 = 100147104):',count((3,3),[]), 16*6259194)
    print('control K=[3] r=7 trivial (x16 -> 995328):',count((3,7),[(1,sq)]))
